//! Independently expected whole-account worn conversion matrices, not developer fixtures.
use gielinor_world::{equipment::{WearType,Event},inventory::Item,simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,worn_item_swap::Rule,CoordGrid};
fn fixture(reverse:bool,member:bool,occupied:bool,holes:usize)->(World,ActorId,i32,i32,usize,usize){let(input,output,from,to)=if reverse{(29775,25644,5,3)}else{(25644,29775,3,5)};let mut w=World::default();w.collision.allocate(3200,3200,0);for(a,b,f,t)in[(25644,29775,3,5),(29775,25644,5,3)]{w.worn_item_swaps.insert(a,Rule{output:b,from_slot:f,to_slot:t,button_operation:2});w.wear_types.types.insert(a,WearType{primary:Some(f),secondary:[None,None],requirements:vec![]});}let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);let mut d=PlayerData::new(1,"Independent worn hammer".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==4{input}else{1931},count:1,vars:0})).unwrap();}for s in(0..28).filter(|s|*s!=4).take(holes){d.inventory.restore_slot(s,None).unwrap();}d.equipment.restore_slot(from,Some(Item{id:input,count:1,vars:0})).unwrap();d.equipment.restore_slot(0,Some(Item{id:1155,count:1,vars:7})).unwrap();if occupied{d.equipment.restore_slot(to,Some(Item{id:999,count:1,vars:9})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();w.tick().unwrap();w.drain_events();(w,a,input,output,from,to)}
#[test]fn four_worn_swaps_cancel_preexisting_weak_crafting(){use gielinor_world::{grinding,tool_crafting::Recipe,held_use::{Handler,Scope,Type,Request}};let mut n=0;for reverse in[false,true]{for member in[false,true]{let(mut w,a,input,output,from,to)=fixture(reverse,member,false,1);{let d=w.data_mut(a).unwrap();d.stats.set_base(12,99);d.stats.set_current(12,99);d.stats.set_fine_xp(12,130344311).unwrap();for(s,id)in[(1,1755),(2,1755),(8,1623),(26,1623)]{d.inventory.restore_slot(s,Some(Item{id,count:1,vars:0})).unwrap();}}let recipe=Recipe{skill:12,exchange:grinding::Recipe{tool:1755,input:1623,output:1607,members:false,animation:Some(8833)},level:20,xp_tenths:500,output_count:1,ticks:10,name:"independent pending gem control",action:"cut",failure:None};for id in[1755,1623]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,1755,1623,Handler::ToolCrafting(recipe)).unwrap();let held=Request{selected_slot:1,selected_id:1755,target_slot:8,target_id:1623};assert!(w.prepare_held_use(a,held).unwrap().is_some());w.finish_held_use(a,held).unwrap();assert!(w.take_tool_crafting_request(a).unwrap().is_none());let before=w.data(a).unwrap().clone();let mut bag=before.inventory.clone();let mut gear=before.equipment.clone();gear.restore_slot(from,None).unwrap();if member{gear.restore_slot(to,Some(Item{id:output,count:1,vars:0})).unwrap();}else{bag.restore_slot(0,Some(Item{id:output,count:1,vars:0})).unwrap();}w.drain_events();w.submit(a,Action::SwapWornItem{slot:from,item:input}).unwrap();for _ in 0..20{w.tick().unwrap();assert_eq!(w.data(a).unwrap().inventory,bag);assert_eq!(w.data(a).unwrap().equipment,gear);assert_eq!(w.data(a).unwrap().stats,before.stats);}assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..})));n+=1;}}assert_eq!(n,4);println!("PG_WORN weak_work_cancelled={n};10tick synthetic queue is interruption control,not gem cadence acceptance");}
